import json, os, time, urllib.request, urllib.error
from pathlib import Path
BASE = os.environ['MCPJAM_API_URL'].rstrip('/') + '/projects/project_fixture'
HEADERS = {'Authorization': 'Bearer ' + os.environ['MCPJAM_API_KEY'], 'Content-Type': 'application/json'}
def api(path, body=None):
    req = urllib.request.Request(BASE + path, data=None if body is None else json.dumps(body).encode(), headers=HEADERS)
    try:
        with urllib.request.urlopen(req, timeout=30) as response:
            return json.load(response)
    except urllib.error.HTTPError as error:
        raise RuntimeError(f'{error.code}: {error.read().decode()}') from None
def save(name, data):
    Path(name).write_text(json.dumps(data, indent=2) + '\n')
if not Path('suite-created.json').exists():
    save('suite-created.json', api('/eval-suites', json.loads(Path('suite.json').read_text())))
suite_id = json.loads(Path('suite-created.json').read_text())['suiteId']
run = api('/eval-runs', {'suiteId': suite_id})
save('run-created.json', run)
print(json.dumps(run), flush=True)
run_id = run['runId']
for _ in range(40):
    status = api('/eval-runs/' + run_id)
    save('run-status.json', status)
    print(json.dumps(status), flush=True)
    if status.get('status') in {'completed', 'failed', 'cancelled', 'timed_out'}:
        break
    time.sleep(2)
else:
    raise RuntimeError('Run has not reached a terminal state; use run-created.json to resume polling.')
for suffix, name in [('iterations', 'iterations.json'), ('decision-summary', 'decision-summary.json')]:
    data = api('/eval-runs/' + run_id + '/' + suffix)
    save(name, data)
    print(name, json.dumps(data), flush=True)
if status.get('status') != 'completed' or status.get('result') not in {'passed', 'pass'}:
    raise SystemExit(1)
